<script setup lang="ts">
import type { ExplorerActivity, ExplorerTransaction } from "../../shared/explorer";
import { formatUsdt } from "#shared/plan";
const props = defineProps<{ admin?: boolean; preview?: boolean }>();
const { t, tr, formatDate } = useLoopI18n();
const { authOpen, copy } = useAppUI();
const route = useRoute();
const search = ref(String(route.query.q || ""));
const selected = ref<ExplorerTransaction | null>(null);
function updateQuery(values: Record<string, string | undefined>) {
  return navigateTo({ path: route.path, query: { ...route.query, ...values, tab: "transactions" } }, { replace: true });
}
const type = computed({ get: () => ["deposit", "withdrawal", "transfer_in", "transfer_out", "commission", "referral_purchase"].includes(String(route.query.type)) ? String(route.query.type) : "all", set: value => { updateQuery({ type: value === "all" ? undefined : value, page: undefined }); } });
const state = computed({ get: () => ["pending", "completed", "rejected"].includes(String(route.query.status)) ? String(route.query.status) : "all", set: value => { updateQuery({ status: value === "all" ? undefined : value, page: undefined }); } });
const period = computed({ get: () => ["7", "30", "90"].includes(String(route.query.period)) ? String(route.query.period) : "all", set: value => { updateQuery({ period: value === "all" ? undefined : value, page: undefined }); } });
const page = computed(() => Math.max(1, Math.min(100000, Number.parseInt(String(route.query.page || 1), 10) || 1)));
const query = computed(() => ({ type: type.value, status: state.value, period: period.value, page: page.value, search: String(route.query.q || "").slice(0, 100) }));
const { data, error, status, refresh } = await useFetch<ExplorerActivity>(props.admin ? "/api/admin/explorer/transactions" : "/api/explorer/transactions", { query, immediate: !props.preview });
watch(() => route.query.q, value => { search.value = String(value || ""); });
function searchRecords() { updateQuery({ q: search.value.trim() || undefined, page: undefined }); }
function clearFilters() { search.value = ""; updateQuery({ q: undefined, type: undefined, status: undefined, period: undefined, page: undefined }); }
function description(item: ExplorerTransaction) {
  if (item.type === "deposit") return tr("Funding request · {amount} USDT", { amount: formatUsdt(item.amount) });
  const memberId = item.description.match(/ ID ([1-9][0-9]*)$/)?.[1];
  if (memberId && item.type === "transfer_out") return t('ui.transfer_to_member_id', { memberId });
  if (memberId && item.type === "transfer_in") return t('ui.transfer_from_member_id', { memberId });
  return tr(item.description);
}
const outgoing = (item: ExplorerTransaction) => item.type === "transfer_out" || item.type === "withdrawal" || item.type === "referral_purchase";
</script>
<template>
  <div v-if="preview" class="explorer-sign-in"><span class="explorer-detail-icon"><AppIcon name="LockKeyhole" :size="27" /></span><h2>{{ t('explorer.signInTitle') }}</h2><p>{{ t('explorer.signInHint') }}</p><button class="button button-orange" @click="authOpen = true">{{ t('ui.sign_in') }}<AppIcon name="ArrowRight" :size="16" /></button></div>
  <div v-else class="explorer-activity">
    <div class="explorer-ledger-note"><AppIcon name="Info" :size="17" /><p>{{ t('explorer.ledgerHint') }}</p></div>
    <div class="explorer-metrics"><article><span>{{ t('explorer.completedCredits') }}</span><strong>{{ formatUsdt(data?.summary.credits || 0) }}<small>USDT</small></strong><p>{{ t('explorer.filteredTotals') }}</p></article><article><span>{{ t('explorer.completedDebits') }}</span><strong>{{ formatUsdt(data?.summary.debits || 0) }}<small>USDT</small></strong><p>{{ t('explorer.filteredTotals') }}</p></article><article><span>{{ t('explorer.pendingAmount') }}</span><strong>{{ formatUsdt(data?.summary.pending || 0) }}<small>USDT</small></strong><p>{{ t('explorer.awaitingSettlement') }}</p></article></div>
    <section class="explorer-panel"><div class="explorer-panel-heading"><div><span class="explorer-eyebrow">{{ t('explorer.activityEyebrow') }}</span><h2>{{ t('explorer.transactions') }}</h2><p>{{ admin ? t('explorer.adminActivityHint') : t('explorer.memberActivityHint') }}</p></div><button class="admin-text-button" :disabled="status === 'pending'" @click="refresh()"><AppIcon name="RefreshCw" :size="15" />{{ t('admin.refresh') }}</button></div><div class="explorer-transaction-controls"><form class="explorer-record-search" @submit.prevent="searchRecords"><label class="search-field"><AppIcon name="Search" :size="16" /><input v-model="search" :aria-label="t('explorer.searchTransactions')" :placeholder="t('explorer.searchTransactions')" maxlength="100" /></label><button class="button button-outline button-small" type="submit">{{ t('admin.search') }}</button></form><div class="explorer-transaction-filters"><AppDropdown v-model="type" :label="t('explorer.filterType')" :options="[{ value: 'all', label: t('explorer.allTypes') }, ...['deposit', 'transfer_in', 'transfer_out', 'commission', 'withdrawal', 'referral_purchase'].map(value => ({ value, label: t(`ui.transaction_${value}`) }))]" /><AppDropdown v-model="state" :label="t('explorer.filterStatus')" :options="[{ value: 'all', label: t('admin.allStatuses') }, ...['pending', 'completed', 'rejected'].map(value => ({ value, label: t(`ui.${value}`) }))]" /><AppDropdown v-model="period" :label="t('explorer.filterPeriod')" :options="[{ value: 'all', label: t('explorer.allTime') }, ...['7', '30', '90'].map(value => ({ value, label: t('explorer.lastDays', { count: value }) }))]" /><button class="admin-text-button" @click="clearFilters">{{ t('explorer.clearFilters') }}</button></div></div>
      <div v-if="error" class="explorer-error" role="alert"><AppIcon name="Info" :size="19" /><div><strong>{{ t('explorer.activityError') }}</strong><button class="admin-text-button" @click="refresh()">{{ t('admin.retry') }}</button></div></div>
      <div v-else class="explorer-table-scroll" :aria-busy="status === 'pending'"><table class="explorer-table"><thead><tr><th>{{ t('explorer.transaction') }}</th><th v-if="admin">{{ t('admin.member') }}</th><th>{{ t('explorer.type') }}</th><th>{{ t('admin.amount') }}</th><th>{{ t('ui.status') }}</th><th>{{ t('explorer.date') }}</th><th><span class="sr-only">{{ t('admin.actions') }}</span></th></tr></thead><tbody><tr v-for="item in data?.items || []" :key="item.id"><td><div class="explorer-transaction-identity"><span class="explorer-transaction-icon" :class="item.status"><AppIcon :name="item.status === 'rejected' ? 'X' : item.status === 'pending' ? 'CalendarDays' : outgoing(item) ? 'ArrowUpRight' : 'ArrowDownLeft'" :size="18" /></span><div><strong>{{ description(item) }}</strong><small>{{ item.id.slice(0, 13) }}…</small></div></div></td><td v-if="admin">ID {{ item.memberId }}</td><td>{{ t(`ui.transaction_${item.type}`) }}</td><td class="explorer-amount" :class="{ outgoing: outgoing(item), rejected: item.status === 'rejected' }">{{ item.status === 'completed' ? outgoing(item) ? '−' : '+' : '' }}{{ formatUsdt(item.amount) }} <small>USDT</small></td><td><span class="admin-status" :class="item.status"><i></i>{{ t(`ui.${item.status}`) }}</span></td><td>{{ formatDate(item.createdAt) }}</td><td><button class="admin-text-button" :aria-label="t('explorer.inspectTransaction', { id: item.id.slice(0, 8) })" @click="selected = item">{{ t('admin.details') }}<AppIcon name="ArrowUpRight" :size="14" /></button></td></tr><tr v-if="!data?.items.length"><td :colspan="admin ? 7 : 6"><div class="explorer-empty"><AppIcon :name="status === 'pending' ? 'LoaderCircle' : 'Search'" :class="{ 'auth-loading': status === 'pending' }" :size="29" /><strong>{{ status === 'pending' ? t('explorer.loading') : t('explorer.noTransactions') }}</strong><p>{{ t('explorer.noTransactionsHint') }}</p></div></td></tr></tbody></table></div><AdminPagination v-if="data && !error" :page="page" :total="data.total" :page-size="data.pageSize" @change="updateQuery({ page: String($event) })" />
    </section>
    <ModalTransition><AppModal v-if="selected" :title="t('explorer.transactionDetails')" @close="selected = null"><div class="admin-dialog"><span class="admin-dialog-icon"><AppIcon name="List" :size="25" /></span><h2>{{ t('explorer.transactionDetails') }}</h2><p>{{ description(selected) }}</p><div class="admin-review-amount">{{ formatUsdt(selected.amount) }}<span>USDT</span></div><dl class="admin-details"><div><dt>{{ t('ui.status') }}</dt><dd><span class="admin-status" :class="selected.status">{{ t(`ui.${selected.status}`) }}</span></dd></div><div><dt>{{ t('explorer.type') }}</dt><dd>{{ t(`ui.transaction_${selected.type}`) }}</dd></div><div v-if="admin"><dt>{{ t('admin.member') }}</dt><dd>ID {{ selected.memberId }}</dd></div><div><dt>{{ t('explorer.transactionId') }}</dt><dd class="admin-wrap-value">{{ selected.id }}<button class="explorer-copy" :aria-label="t('explorer.copyId')" @click="copy(selected.id, t('explorer.idCopied'))"><AppIcon name="Copy" :size="14" /></button></dd></div><div><dt>{{ t('explorer.internalWallet') }}</dt><dd class="admin-wrap-value">{{ selected.walletId }}</dd></div><div><dt>{{ t('explorer.date') }}</dt><dd>{{ formatDate(selected.createdAt, { year: 'numeric', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' }) }}</dd></div><div v-if="selected.reference"><dt>{{ t('admin.reference') }}</dt><dd class="admin-wrap-value">{{ selected.reference }}</dd></div><div v-if="selected.reviewedAt"><dt>{{ t('admin.reviewedAt') }}</dt><dd>{{ formatDate(selected.reviewedAt) }}</dd></div><div v-if="selected.note"><dt>{{ t('admin.note') }}</dt><dd class="admin-wrap-value">{{ selected.note }}</dd></div></dl><p class="admin-callout">{{ t('explorer.recordHint') }}</p></div></AppModal></ModalTransition>
  </div>
</template>
